'use strict';
const TN_UI7={managementView,coffeeView,bind,gameRender6,gameContext6,gameDrawScene6,gameAssetContext12,showDigest6};
let tnMapLayer7='none',tnManageTab7='priorities',tnManageRoot7=state,tnSelectedStore7=null;
function tnStockDialog7(id){
 try{
  const s=tnStore7(id),agreement=state.bootstrap6.suppliers.find(a=>a.location===id&&a.status==='active'),forecast=tycoonForecast7(id),stock=cafeCoffeeStatus6(id,s.blend),incoming=state.bootstrap6.orders.filter(o=>o.blend===s.blend&&o.city===loc(id).city&&o.received===null).reduce((n,o)=>n+o.kg,0),needed=Math.ceil(Math.max(0,forecast.potential*(menuSummary(s).dose||.018)-stock.kg-incoming)),q=needed>=5?supplierCoffeeQuote6(agreement?.provider||'local',id,s.blend,Math.min(100,needed)):null;
  show(`<h2>${esc(loc(id).name)} · dnešní potřeba kávy</h2>${rows([['Použitelná společná zásoba',number(stock.kg,1)+' kg'],['Zaplacené příjezdy do města',number(incoming,1)+' kg'],['Provozní model před omezením zásobou',forecast.potential+' hostů'],['Chybějící doplnění',needed+' kg']])}<p class="sub">Příjezdy zatím nejsou skladem. Nový nákup dorazí nejdříve příští týden; další kavárny sdílí stejnou kávu.</p>${q?`<p>${q.kg} kg · ${COFFEE_SUPPLIERS6[q.provider].name} · ${money(q.cost)} · T${q.due}</p><button class="primary" id="tnStockOrder7" ${state.cash<q.cost?'disabled':''}>Zkontrolovat jednorázový nákup</button>`:'<p>Dnešní model a zaplacené příjezdy nevyžadují novou objednávku alespoň 5 kg.</p>'}<button class="soft" id="tnStockAgreement7">Smlouva a pravidelné dodávky</button>`);
  el('tnStockAgreement7').onclick=()=>gameSupplierDialog6(id);
  if(q)el('tnStockOrder7').onclick=()=>confirmAction('Zaplatit konkrétní kávu?',q.kg+' kg · '+money(q.cost)+' · doručení od T'+q.due+'. Platba vytváří zásobu na cestě.',()=>orderSupplierCoffee6(q.provider,id,q.blend,q.kg,q),'Objednat a zaplatit');
 }catch(e){toast(e.message);}
}
const TN_GOALS7={profit:'Zisk',service:'Obsluha a fronty',quality:'Kvalita kávy a týmu'};
function tnCoffeeRetail7(id){const spec=coffeeSpec7(id);if(!spec){coffeeTab6='products';el('modal').close();goto('coffee');return;}productDevelopmentDialog6();for(const [field,value] of Object.entries({productName6:spec.data.name,productBlend6:id,productBrand6:spec.data.brand,productPack6:spec.data.pack,productStory6:spec.data.story,productCity6:spec.city}))el(field).value=value;el('productName6').oninput();}
const TN_RIGHT_LABELS7={price:'Ceny menu ±5 Kč',marketing:'Marketing ±500 Kč / týden',shifts:'Automatické směny',staff:'Návrh doplnění týmu',service:'Placený servis',training:'Placené školení',equipment:'Návrh vybavení',coffee:'Návrh jiné dostupné kávy'};
function tnButton7(label,attr,kind='soft'){return `<button class="${kind}" ${attr}>${esc(label)}</button>`;}
function tnRoute7(x){if(digestActive6!==null)closeDigest6();if(x.type==='approval'){el('modal').close();goto('management');tnManageTab7='decisions';render();}else if(['operation','profit'].includes(x.type))tnDiagnosisDialog7(x.target);else if(x.type==='stock')tnStockDialog7(x.target);else if(x.type==='seats'){el('modal').close();gameReturn6(x.target);gameLayer6='cafe';render();el('gameEditCafe6')?.click();}else{el('modal').close();goto(x.view);}}
function tnPrioritiesHtml7(report){if(!report)return state.stores.length?'<p class="sub">Nové priority vzniknou po dalším uzavřeném týdnu. Provozní varianty a mandáty už najdeš v Manažerech.</p>':'<p class="sub">První doporučení vzniknou po uzavření skutečného týdne. Vyber prostor nebo připravovaný podnik na mapě.</p>';return `<div class="tn-priorities7">${report.items.map((x,i)=>`<article class="tn-priority7"><span class="tn-number7">${i+1}</span><div><strong>${esc(x.title)}</strong><p>${esc(x.evidence)}</p><small>${esc(x.effect||'Cena a přínos budou ověřeny v současném stavu.')}${x.cost!==null?' · '+money(x.cost):''}</small><button class="soft" data-tn-priority7="${i}">${esc(x.action)}</button></div></article>`).join('')||'<p class="sub">V uzavřeném týdnu se neobjevily sledované problémy. Prověř cíle oddělení a možnosti expanze.</p>'}</div>`;}
function tnPrioritiesBind7(report,root=document){root.querySelectorAll('[data-tn-priority7]').forEach(b=>b.onclick=()=>tnRoute7(report.items[Number(b.dataset.tnPriority7)]));}
function tnDecisionsHtml7(){const m=state.tycoon7;return `<h2>Rozhodnutí a skutečný výsledek</h2><p class="sub">Návrh neplatí nic před schválením. Cena i autor se při schválení znovu ověří.</p>${m.proposals.filter(x=>x.status==='pending').map(x=>`<article class="tn-proposal7"><strong>${esc(loc(x.target).name)} · ${esc(x.name)}</strong><p>${esc(x.action.label)}</p>${rows([['Platba nyní',money(x.quote.cost)],['Nový závazek / týden',money(x.quote.weekly)],['Odhad změny výsledku',money(x.quote.after.profit-x.quote.before.profit)+'/týden']])}<p class="sub">Nabídka T${x.week}${x.week!==state.week?' · potřebuje aktualizaci':''}; rezerva ${money(x.quote.reserved)}. ${x.quote.affordable?'':'Současná nabídka nesplňuje rezervu.'}</p><div class="actions"><button class="soft" data-tn-refresh7="${x.id}">Aktualizovat</button><button class="primary" data-tn-approve7="${x.id}">Zkontrolovat a schválit</button><button class="quiet" data-tn-reject7="${x.id}">Odmítnout</button></div></article>`).join('')||'<p class="sub">Žádný nový návrh ke schválení.</p>'}<h3>Poslední provedené kroky</h3>${m.decisions.slice(-20).reverse().map(r=>`<details class="tn-decision7"><summary>T${r.week} · ${esc(loc(r.target).name)} · ${esc(r.action.label)}</summary><p>${esc(r.author)} · ${esc(TN_GOALS7[r.goal])}</p>${rows([['Platba a nový týdenní závazek',money(r.cost)+' / '+money(r.weekly)],['Odhad před změnou',money(r.before.profit)+' · '+r.before.served+' hostů'],['Odhad po změně',money(r.expected.profit)+' · '+r.expected.served+' hostů'],['Skutečný uzavřený provoz',r.actual?money(r.actual.profit)+' · '+r.actual.served+' hostů':'Čeká na provoz']])}<p class="sub">${esc(r.reason)} Rozdíl od odhadu zahrnuje všechny další vlivy týdne.</p></details>`).join('')||'<p class="sub">Po zapnutí mandátu nebo potvrzení provozní varianty tu vznikne historie.</p>'}`;}
function tnDepartmentsHtml7(){return `<h2>Oddělení s odpovědností</h2><p class="sub">Ředitel a skutečný tým potřebují kancelářská místa a mzdy. Cíl ani jeho změna nedává prostředky zdarma.</p><div class="tn-department-grid7">${Object.entries(TN_DEPARTMENTS7).map(([key,c])=>{const p=state.tycoon7.departments[key],e=state.organization.executives[key],last=state.tycoon7.departmentHistory.filter(r=>r.key===key).at(-1),value=last?.after[c.metric];return `<article class="card"><span class="eyelabel">${c.name}</span><h3>${esc(e.manager?.name||'Chybí ředitel')}</h3><p>${state.departments[key]} lidí · ${money(state.departments[key]*DEPARTMENTS[key].salary*(1+ECONOMY_RULES6.employer))} náklad týmu týdně</p><p>${esc(c.goal)} · cíl ${p.target}${key==='finance'?' tis. Kč':''}</p>${last?`<p class="${last.met?'good':'bad'}">T${last.week}: ${value===null?'Bez měřitelného odběru':number(value,1)} / tehdejší cíl ${last.plan.target}</p><p class="sub">${esc(last.text)}</p><small>Platba zásahu ${money(last.cost)} · IT ${money(last.projectPaid)} · ředitel ${money(last.director)}. ${last.met?'Cíl splněn.':'Cíl nesplněn.'}</small>`:'<p class="sub">Vyhodnocení vznikne po týdnu s aktivním cílem.</p>'}<div class="actions"><button class="soft" data-tn-department7="${key}">Cíl a rozpočet</button><button class="quiet" data-tn-department-history7="${key}">Historie</button></div><small>${p.enabled?'Aktivní odpovědnost':'Vypnuté nové řízení'}</small></article>`;}).join('')}</div><button class="soft" data-goto="organization">Obsadit vedení a pravomoci</button><button class="soft" data-goto="board">Cíle a hlasování boardu</button>`;}
managementView=function(){const stores=state.stores.filter(s=>!s.franchise),report=tycoonReport7();return `<section class="card tn-control7"><span class="eyelabel">ŘÍZENÍ FIRMY</span><h2>Co teď rozhodnout</h2><div class="tn-tabs7" role="navigation" aria-label="Řídicí přehled">${[['priorities','Priority týdne'],['managers','Manažeři'],['departments','Oddělení'],['decisions','Rozhodnutí'],['advanced','Nákup a board']].map(([id,label])=>`<button class="${tnManageTab7===id?'primary':'soft'}" data-tn-tab7="${id}" ${tnManageTab7===id?'aria-current="page"':''}>${label}</button>`).join('')}</div>${tnManageTab7==='priorities'?`<p class="sub">${report?'Nejvýše tři priority z T'+report.week+'. Tlačítka otevřou dnešní stav; minulé výsledky zůstávají zachované.':state.stores.length?'Současný provoz, cíle a pravomoci.':'Základ: placený prostor, tým a dodávky kávy.'}</p>${tnPrioritiesHtml7(report)}`:tnManageTab7==='managers'?`<h3>Cíle a pravomoci kaváren</h3><div class="tn-manager-list7">${stores.map(s=>{const p=tnMandate7(s.id),owner=owner5(s);return `<article><div><strong>${esc(loc(s.id).name)}</strong><small>${esc(owner?.person.name||'Zakladatel')} · ${p.enabled?TN_GOALS7[p.goal]:'Nový mandát vypnutý'} · limit ${money(p.budget)}</small></div><button class="soft" data-tn-manager7="${s.id}">Nastavit řízení</button><button class="quiet" data-tn-diagnosis7="${s.id}">Provoz</button></article>`;}).join('')||'<p>Nejdřív otevři vlastní kavárnu. První týdny můžeš řídit jako zakladatel.</p>'}</div>`:tnManageTab7==='departments'?tnDepartmentsHtml7():tnManageTab7==='decisions'?tnDecisionsHtml7():''}</section>${tnManageTab7==='advanced'?TN_UI7.managementView():''}`;};
function tnManagerDialog7(id){const s=tnStore7(id),p=tnMandate7(id),owner=owner5(s);show(`<span class="eyelabel">ODPOVĚDNOST KAVÁRNY</span><h2>${esc(loc(id).name)}</h2><p>${esc(owner?.person.name||'Zakladatel')} ${owner?.automatic?'má provozní pravomoc.':'· obsazení role a pravomoc nastavíš ve správě vedoucích.'}</p><div class="fields">${field('Hlavní cíl',`<select id="tnGoal7">${Object.entries(TN_GOALS7).map(([k,n])=>option(k,n,p.goal)).join('')}</select>`)}${field('Limit plateb a nových týdenních závazků',input('tnBudget7',p.budget,0,100000,500))}${field('Schvalovat částku nad',input('tnApproval7',p.approval,0,100000,500))}${field('Chráněná rezerva (týdny)',input('tnReserve7',p.reserve,1,8,1))}${field('Nejnižší průměrná cena menu',input('tnMinPrice7',p.minPrice,40,400,1))}${field('Nejvyšší průměrná cena menu',input('tnMaxPrice7',p.maxPrice,40,400,1))}${field('Cílová fronta (minuty)',input('tnWait7',p.wait,0,30,1))}${field('Cílová kvalita',input('tnQuality7',p.quality,25,99,1))}</div><fieldset class="tn-rights7"><legend>Co smí manažer změnit</legend>${TN_RIGHTS7.map(k=>`<label><input type="checkbox" data-tn-right7="${k}" ${p.rights[k]?'checked':''}>${TN_RIGHT_LABELS7[k]}</label>`).join('')}</fieldset><p class="sub">Nábor, nové vybavení a změna směsi vždy čekají na tebe. Ruční rozpis a původní vypnuté pravomoci ceny/marketingu se respektují. Limit počítá nábor a také přírůstek mzdy či marketingu; další týdny se platí z provozu.</p><label class="checkbox-line"><input type="checkbox" id="tnEnabled7" ${p.enabled?'checked':''}> Zapnout řízení podle tohoto mandátu</label><div class="actions"><button class="primary" id="tnSaveManager7">Uložit mandát</button><button class="soft" id="tnManagerPeople7">Obsadit vedoucího</button><button class="soft" id="tnManagerCompare7">Porovnat provozní varianty</button></div>`);el('tnSaveManager7').onclick=()=>{const policy={enabled:el('tnEnabled7').checked,goal:el('tnGoal7').value,rights:Object.fromEntries([...document.querySelectorAll('[data-tn-right7]')].map(e=>[e.dataset.tnRight7,e.checked]))};for(const [k,f] of Object.entries({budget:'tnBudget7',approval:'tnApproval7',reserve:'tnReserve7',minPrice:'tnMinPrice7',maxPrice:'tnMaxPrice7',wait:'tnWait7',quality:'tnQuality7'}))policy[k]=Number(el(f).value);try{setTycoonMandate7(id,policy);persist();render();el('modal').close();toast('Mandát kavárny uložen.');}catch(e){toast(e.message);}};el('tnManagerPeople7').onclick=()=>{el('modal').close();goto('people');};el('tnManagerCompare7').onclick=()=>tnDiagnosisDialog7(id);}
function tnQuoteDialog7(id,q){show(`<span class="eyelabel">DNEŠNÍ PROVOZNÍ VARIANTA</span><h2>${esc(q.action.label)}</h2><p>${esc(loc(id).name)}</p>${rows([['Platba nyní',money(q.cost)],['Nové místní fixní náklady týdně',money(q.weekly)],['Odhad před / po změně',money(q.before.profit)+' / '+money(q.after.profit)],['Obsloužení před / po změně',q.before.served+' / '+q.after.served],['Dnešní zásoba pro odhad',number(q.after.coffeeKg,1)+' kg'],['Neobslouženo kvůli kávě',q.after.stockLost]])}<p class="sub">Místní výsledek po DPH, kávě, mzdách a nákladech; jídlo a balení drží poslední známý příspěvek. Sdílená zásoba se může spotřebovat jinde, zásilky a příští počasí nejsou slibem tohoto odhadu.</p><div class="actions"><button class="primary" id="tnApplyPreview7" ${state.over||state.cash<q.cost?'disabled':''}>Potvrdit změnu · ${money(q.cost)}</button><button class="soft" id="tnPreviewBack7">Zpět na porovnání</button></div>`);el('tnPreviewBack7').onclick=()=>tnDiagnosisDialog7(id);el('tnApplyPreview7').onclick=()=>confirmAction('Provést změnu v kavárně?',esc(q.action.label)+' · '+money(q.cost)+' nyní a +'+money(q.weekly)+' náklady týdně. Přepočet proběhne před platbou.',()=>applyTycoonPreview7(id,q.action,q),'Provést změnu');}
function tnDiagnosisDialog7(id){try{const d=cafeDiagnosis7(id),options=tycoonOptions7(id,false),hold=options.find(x=>x.action.kind==='hold'),ordered=options.filter(x=>x.action.kind!=='hold').sort((a,b)=>b.after.profit-a.after.profit);show(`<span class="eyelabel">KAVÁRNA · PROVOZNÍ ROZBOR</span><h2>${esc(loc(id).name)}</h2><p class="sub">${d.week?'Skutečný uzavřený T'+d.week+'. Dnešní varianty jsou oddělené od minulého provozu.':'Provoz ještě není odehraný. Varianty ukazují dnešní možnosti.'}</p>${d.week?`${rows([['Příchozí / obsloužení',d.demand+' / '+d.served],['Místní výsledek',money(d.profit)],...d.reasons.map(r=>[r.label,r.count+' hostů'])])}<details><summary>Špičky a pokrytí směn</summary><div class="table-scroll"><table class="data"><thead><tr><th>Den / čas</th><th>Hosté</th><th>Odchody</th><th>Lidé</th></tr></thead><tbody>${d.peaks.slice(0,6).map(p=>`<tr><td>${DAYS5[p.day]} · ${['7–11','11–15','15–19'][p.period]}</td><td>${p.arrivals}</td><td>${p.lost}</td><td>${p.workers}</td></tr>`).join('')}</tbody></table></div><p>Poruchy: ${d.faults} desetiminutových úseků. Chybějící obsazení dnešního rozpisu: ${d.gap} směn.</p></details>`:''}<h3>Porovnání dnešních zásahů</h3><p class="sub">Beze změny: ${money(hold.after.profit)} / týden, ${hold.after.served} hostů, ${hold.after.stockLost} bez kávy. Návrhy nevytvářejí zásobu ani zaměstnance zdarma.</p><div class="tn-variants7">${ordered.map((q,i)=>`<article><div><strong>${esc(q.action.label)}</strong><small>${money(q.cost)} nyní · +${money(q.weekly)} týdně</small></div><span class="${q.after.profit>=hold.after.profit?'good':'bad'}">${q.after.profit-hold.after.profit>0?'+':''}${money(q.after.profit-hold.after.profit)}<small>Změna výsledku / týden</small><small>${q.after.served-hold.after.served>=0?'+':''}${q.after.served-hold.after.served} hostů</small></span><button class="soft" data-tn-variant7="${i}">Detail</button></article>`).join('')||'<p>Žádná další dostupná varianta. Prověř tým, rozpis a zásoby.</p>'}</div><div class="actions"><button class="soft" id="tnDiagnosisSupply7">Dodávky kávy</button><button class="soft" id="tnDiagnosisLayout7">Návrh prostoru</button><button class="soft" id="tnDiagnosisTeam7">Jmenný tým a rozpis</button><button class="quiet" id="tnDiagnosisManager7">Mandát manažera</button></div>`);document.querySelectorAll('[data-tn-variant7]').forEach(b=>b.onclick=()=>tnQuoteDialog7(id,ordered[Number(b.dataset.tnVariant7)]));el('tnDiagnosisSupply7').onclick=()=>gameSupplierDialog6(id);el('tnDiagnosisManager7').onclick=()=>tnManagerDialog7(id);el('tnDiagnosisTeam7').onclick=()=>{crewSelected5=id;crewTab6='teams';el('modal').close();goto('crew');};el('tnDiagnosisLayout7').onclick=()=>{el('modal').close();gameReturn6(id);gameLayer6='cafe';render();el('gameEditCafe6')?.click();};}catch(e){toast(e.message);}}
function tnDepartmentDialog7(key){const c=TN_DEPARTMENTS7[key],p=state.tycoon7.departments[key];show(`<span class="eyelabel">ODPOVĚDNOST ODDĚLENÍ</span><h2>${c.name}</h2><p>${esc(c.goal)} · ${c.direction==='min'?'nejvýše':'alespoň'} cílová hodnota.</p><div class="fields">${field(c.goal,input('tnDeptTarget7',p.target,0,100,1))}${field('Limit zásahu / týden',input('tnDeptBudget7',p.budget,0,100000,1000))}${field('Chráněná rezerva / týdny',input('tnDeptReserve7',p.reserve,1,8,1))}${key==='it'?field('Projekt s předností',`<select id="tnDeptProject7">${option('loyalty','Věrnostní aplikace',p.project)}${option('eshop','E-shop',p.project)}</select>`):''}${key==='product'?field('Vyvíjená receptura',`<select id="tnDeptBlend7">${blendOptions(p.blend)}</select>`):''}</div><label class="checkbox-line"><input type="checkbox" id="tnDeptEnabled7" ${p.enabled?'checked':''}> Použít tento cíl místo dosavadních automatických pravidel</label><p class="sub">${key==='hr'?'HR při chybějícím pokrytí doporučí konkrétní nábor; novou mzdu potvrzuješ v provozním porovnání.':'Ředitel provádí skutečné dostupné kroky v limitu a rezervě.'} Již schválené IT rozpočty zůstávají splatné; změníš je v digitálních službách. Minulá hodnocení uchovávají původní cíle.</p><button class="primary" id="tnSaveDept7">Uložit odpovědnost</button>`);el('tnSaveDept7').onclick=()=>{try{setDepartmentGoal7(key,{enabled:el('tnDeptEnabled7').checked,target:Number(el('tnDeptTarget7').value),budget:Number(el('tnDeptBudget7').value),reserve:Number(el('tnDeptReserve7').value),project:el('tnDeptProject7')?.value||p.project,blend:el('tnDeptBlend7')?.value||p.blend});persist();render();el('modal').close();toast('Cíl oddělení uložen.');}catch(e){toast(e.message);}};}
function tnDepartmentHistory7(key){const c=TN_DEPARTMENTS7[key],rows7=state.tycoon7.departmentHistory.filter(r=>r.key===key).slice(-26).reverse();show(`<h2>${c.name} · výsledky a cíle</h2>${rows7.map(r=>`<article class="tn-decision7"><strong>T${r.week} · ${esc(r.owner)} · ${r.met?'splněno':'nesplněno'}</strong>${rows([['Tehdejší cíl',r.plan.target],['Před / po týdnu',(r.before[c.metric]===null?'—':number(r.before[c.metric],1))+' / '+(r.after[c.metric]===null?'—':number(r.after[c.metric],1))],['Platba / tým / ředitel',money(r.cost)+' / '+money(r.wages)+' / '+money(r.director)],['IT vývoj skutečně v účetnictví',money(r.projectPaid)]])}<p>${esc(r.text)}</p></article>`).join('')||'<p>Zatím bez týdne s aktivním cílem.</p>'}<p class="sub">Měříme skutečný stav celé odpovědné oblasti. Změnu nelze připsat výhradně jednomu zásahu.</p>`);}
function tnDecisionBind7(root=document){root.querySelectorAll('[data-tn-manager7]').forEach(b=>b.onclick=()=>tnManagerDialog7(b.dataset.tnManager7));root.querySelectorAll('[data-tn-diagnosis7]').forEach(b=>b.onclick=()=>tnDiagnosisDialog7(b.dataset.tnDiagnosis7));root.querySelectorAll('[data-tn-department7]').forEach(b=>b.onclick=()=>tnDepartmentDialog7(b.dataset.tnDepartment7));root.querySelectorAll('[data-tn-department-history7]').forEach(b=>b.onclick=()=>tnDepartmentHistory7(b.dataset.tnDepartmentHistory7));root.querySelectorAll('[data-tn-refresh7]').forEach(b=>b.onclick=()=>act(()=>refreshTycoonProposal7(b.dataset.tnRefresh7),'Nabídka aktualizována.'));root.querySelectorAll('[data-tn-reject7]').forEach(b=>b.onclick=()=>act(()=>decideTycoonProposal7(b.dataset.tnReject7,false),'Návrh odmítnut.'));root.querySelectorAll('[data-tn-approve7]').forEach(b=>b.onclick=()=>{const x=state.tycoon7.proposals.find(x=>x.id===b.dataset.tnApprove7);confirmAction('Schválit zásah manažera?',esc(x.action.label)+' · '+money(x.quote.cost)+' nyní a +'+money(x.quote.weekly)+' týdně. Změněná nabídka se neprovede.',()=>decideTycoonProposal7(x.id,true),'Schválit přesnou nabídku');});}
