function tnMapLabels7(){if(!gameMode6||gameLayer6!=='city')return;const rows7=cityDecisionMap7(gameCity6),values=rows7.map(r=>tnMapLayer7==='demand'?r.demand:tnMapLayer7==='rent'?r.rent:tnMapLayer7==='competition'?r.competitors:r.profit??0),min=Math.min(...values),max=Math.max(...values);for(const [i,row] of rows7.entries()){for(const button of [el('game-label-'+row.id),document.querySelector('[data-game-fallback6="'+row.id+'"]')].filter(Boolean)){let chip=button.querySelector('.tn-map-chip7');if(tnMapLayer7==='none'){chip?.remove();button.style.removeProperty('--tn-map-color');continue;}if(!chip){chip=document.createElement('small');chip.className='tn-map-chip7';button.append(chip);}chip.textContent=tnLayerValue7(row);const score=(values[i]-min)/Math.max(1,max-min),favorable=['demand','profit'].includes(tnMapLayer7)?score:1-score;button.style.setProperty('--tn-map-color',favorable>.66?'#447d61':favorable>.33?'#96743d':'#a05249');}}}
function tnMapCompare7(){const list=cityDecisionMap7(gameCity6);show(`<span class="eyelabel">ROZHODOVÁNÍ O EXPANZI</span><h2>${esc(gameCity6)} · porovnání adres</h2><p class="sub">Poptávka je veřejný model lokality; nájem platí pro startovací prostor. Přesnější placený průzkum a další typy prostoru zůstávají ve správě expanze.</p><div class="table-scroll"><table class="data"><thead><tr><th>Adresa</th><th>Hosté / týden</th><th>Nájem / týden</th><th>Blízcí soupeři</th><th></th></tr></thead><tbody>${list.map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>${({owned:'Tvoje kavárna',opening:'Připravovaný podnik',rival:'Obsazeno soupeřem',free:'Volný prostor'})[r.status]}${r.locked?' · město zamčené':''}</small></td><td>${r.demand}</td><td>${money(r.rent)}</td><td>${r.competitors}</td><td><button class="soft" data-tn-address7="${r.id}" ${r.locked?'disabled':''}>${r.status==='free'?'Investiční odhad':r.status==='owned'?'Provoz':'Na mapě'}</button></td></tr>`).join('')}</tbody></table></div>`);document.querySelectorAll('[data-tn-address7]').forEach(b=>b.onclick=()=>{const row=list.find(r=>r.id===b.dataset.tnAddress7);if(row.status==='free')tnAddressDialog7(row.id);else if(row.status==='owned')tnDiagnosisDialog7(row.id);else{el('modal').close();gamePick6({kind:'address',id:row.id});}});}
